function updatePolySim() {
    const p2 = parseFloat(document.getElementById('p-c2').value) || 0;
    const p1 = parseFloat(document.getElementById('p-c1').value) || 0;
    const p0 = parseFloat(document.getElementById('p-c0').value) || 0;

    const q2 = parseFloat(document.getElementById('q-c2').value) || 0;
    const q1 = parseFloat(document.getElementById('q-c1').value) || 0;
    const q0 = parseFloat(document.getElementById('q-c0').value) || 0;

    // Sum
    const s2 = p2 + q2;
    const s1 = p1 + q1;
    const s0 = p0 + q0;

    // Diff
    const d2 = p2 - q2;
    const d1 = p1 - q1;
    const d0 = p0 - q0;

    function formatPoly(c2, c1, c0) {
        let parts = [];
        if (c2 !== 0) parts.push(`${c2}x²`);
        if (c1 > 0) parts.push(`+ ${c1}x`);
        else if (c1 < 0) parts.push(`- ${Math.abs(c1)}x`);
        if (c0 > 0) parts.push(`+ ${c0}`);
        else if (c0 < 0) parts.push(`- ${Math.abs(c0)}`);
        return parts.length > 0 ? parts.join(' ') : '0';
    }

    document.getElementById('poly-sum-res').innerText = formatPoly(s2, s1, s0);
    document.getElementById('poly-diff-res').innerText = formatPoly(d2, d1, d0);
}

