function updateZeroProdSim() {
    const p = parseInt(document.getElementById('input-root-p').value, 10);
    const q = parseInt(document.getElementById('input-root-q').value, 10);

    document.getElementById('badge-root-p').innerText = 'p = ' + p;
    document.getElementById('badge-root-q').innerText = 'q = ' + q;

    const pSign = (p >= 0) ? `- ${p}` : `+ ${Math.abs(p)}`;
    const qSign = (q >= 0) ? `- ${q}` : `+ ${Math.abs(q)}`;

    document.getElementById('zero-prod-eq').innerText = `(x ${pSign})(x ${qSign}) = 0`;
    document.getElementById('fac-1-eq').innerText = `x ${pSign} = 0`;
    document.getElementById('fac-2-eq').innerText = `x ${qSign} = 0`;
    document.getElementById('root-1-res').innerText = `x = ${p}`;
    document.getElementById('root-2-res').innerText = `x = ${q}`;

    const roots = Array.from(new Set([p, q])).sort((a,b) => a - b);
    document.getElementById('zero-prod-pill').innerText = `Solution Set: {${roots.join(', ')}}`;
}

document.addEventListener('DOMContentLoaded', () => {
    updateZeroProdSim();
});

