function updateTaxSim() {
    const inc = parseInt(document.getElementById('input-tax-inc').value, 10);
    document.getElementById('badge-tax-inc').innerText = '$' + inc.toLocaleString();

    const b1Cap = 9075;
    const b2Cap = 36900;

    let b1Tax = 0;
    let b2Tax = 0;
    let b3Tax = 0;

    if (inc <= b1Cap) {
        b1Tax = inc * 0.10;
    } else if (inc <= b2Cap) {
        b1Tax = b1Cap * 0.10;
        b2Tax = (inc - b1Cap) * 0.15;
    } else {
        b1Tax = b1Cap * 0.10;
        b2Tax = (b2Cap - b1Cap) * 0.15;
        b3Tax = (inc - b2Cap) * 0.25;
    }

    const totalTax = b1Tax + b2Tax + b3Tax;
    const effRate = inc > 0 ? ((totalTax / inc) * 100).toFixed(1) : 0;

    document.getElementById('tax-owed-val').innerText = '$' + Math.round(totalTax).toLocaleString();
    document.getElementById('tax-rate-val').innerText = effRate + '%';

    document.getElementById('bracket-1-line').innerText = `• 10% on first $9,075: $${Math.round(b1Tax).toLocaleString()}`;
    document.getElementById('bracket-2-line').innerText = `• 15% on $9,075 - $36,900: $${Math.round(b2Tax).toLocaleString()}`;
    document.getElementById('bracket-3-line').innerText = `• 25% on amount over $36,900: $${Math.round(b3Tax).toLocaleString()}`;
}

function setTaxIncome(val) {
    document.getElementById('input-tax-inc').value = val;
    updateTaxSim();
}

document.addEventListener('DOMContentLoaded', () => {
    updateTaxSim();
});
